export default {"id":"launchkey-level-13","number":13,"title":"Ableton Live 12 Standard Native Control Surface","skillBand":"Textbook","duration":"From the course textbook","summary":"The primary digital audio workstation environment for this academy is Ableton Live 12 Standard. Dedicated bidirectional integration between the Launchkey MK4 61 and Ableton Live 12 relies on the official Python control surface script named ","modules":[{"id":"launchkey-m-13-1-1","code":"13.1","title":"Ableton Live 12 Standard Native Control Surface","blurb":"The primary digital audio workstation environment for this academy is Ableton Live 12 Standard. Dedicated bidirectional integration between the Launchkey MK4 61 and Ableton Live 12 relies on the official Python control surface script named ","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-38","title":"Section overview","blocks":[{"type":"step","title":"Section 13.1 — Control Surface Script Installation & MIDI Routing","blocks":[{"type":"heading","text":"Module Overview","level":3},{"type":"prose","html":"The primary digital audio workstation environment for this academy is <strong>Ableton Live 12 Standard</strong>. Dedicated bidirectional integration between the Launchkey MK4 61 and Ableton Live 12 relies on the official Python control surface script named <code>Launchkey MK4</code>. This module details driver verification, script assignment, DAW port binding, the authoritative Track/Sync/Remote matrix, MPE port deactivation, and visual handshake validation."},{"type":"heading","text":"Learning Objectives","level":3},{"type":"list","items":["Verify firmware and OS driver prerequisites prior to control surface initialization.","Select the official <code>Launchkey MK4</code> control surface script in Ableton Live 12.","Bind the Control Surface Input and Output strictly to the dedicated <strong>DAW ports</strong>.","Configure the authoritative 4-row <strong>Track / Sync / Remote</strong> routing matrix.","Formulate why the <code>MPE</code> checkbox must remain disabled by default.","Verify successful control surface initialization via optical pad feedback and the Session View 2×8 focus ring.","Detail legacy compatibility limits across Ableton Live 11.3.26+ and Live 10."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-13-1-1","title":"13.1.1: Prerequisites: Firmware & Driver Baseline","blocks":[{"type":"step","title":"13.1.1: Prerequisites: Firmware & Driver Baseline","blocks":[{"type":"prose","html":"Before configuring Ableton Live 12:"},{"type":"list","items":["<strong>Firmware Check</strong>: The Launchkey MK4 61 must be running current firmware flashed via Novation Components (Module 3). Base production firmware fails the Live 12 control surface handshake.","<strong>Windows Workstations</strong>: The dedicated Novation Windows USB Driver must be installed.","<strong>Live Version Floor</strong>: Live must be version <strong>12.0.25 or higher</strong> (or legacy Live <strong>11.3.26 or higher</strong>)."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-13-1-2","title":"13.1.2: Control Surface Script Selection & Port Binding","blocks":[{"type":"step","title":"13.1.2: Control Surface Script Selection & Port Binding","blocks":[{"type":"prose","html":"Navigate to Live's MIDI preferences:"},{"type":"list","items":["<strong>Windows</strong>: <code>Options &gt; Settings...</code> -&gt; <code>Link, Tempo &amp; MIDI</code> tab.","<strong>macOS</strong>: <code>Live &gt; Settings...</code> -&gt; <code>Link, Tempo &amp; MIDI</code> tab."],"ordered":false},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">       ABLETON LIVE 12 CONTROL SURFACE ROW CONFIGURATION\n+------------------+-----------------------------+-----------------------------+\n| Control Surface  | Input Port                  | Output Port                 |\n+------------------+-----------------------------+-----------------------------+\n| **Launchkey MK4**| **MIDIIN2 (LKMK4 MIDI)**    | **MIDIOUT2 (LKMK4 MIDI)**   |\n|                  | *(macOS: Launchkey MK4 DAW)*| *(macOS: Launchkey MK4 DAW)*|\n+------------------+-----------------------------+-----------------------------+</pre>"},{"type":"prose","html":"<em>CRITICAL BINDING RULE</em>: Never select the primary <code>Launchkey MK4 61 MIDI</code> port in the Control Surface row. The Control Surface script requires the dedicated <strong>DAW In / DAW Out</strong> interface (Interface 2)."}]}],"minutes":8},{"id":"launchkey-l-13-1-3","title":"13.1.3: Authoritative Live 12 Track / Sync / Remote Routing Matrix","blocks":[{"type":"step","title":"13.1.3: Authoritative Live 12 Track / Sync / Remote Routing Matrix","blocks":[{"type":"prose","html":"Beneath the Control Surface table, configure the <code>MIDI Ports</code> routing flags exactly as specified in Novation’s official integration standard:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|              AUTHORITATIVE LIVE 12 TRACK / SYNC / REMOTE MATRIX               |\n+---------------------------------------+-----------+-----------+---------------+\n| MIDI Port (Windows / macOS)           | Track     | Sync      | Remote        |\n+---------------------------------------+-----------+-----------+---------------+\n| **Input: Launchkey MK4 61 MIDI**      | **ON**    | Off       | **ON**        |\n| **Input: Launchkey MK4 61 DAW In**    | **ON**    | Off       | **ON**        |\n| **Output: Launchkey MK4 61 MIDI**     | **ON**    | **ON**    | **ON**        |\n| **Output: Launchkey MK4 61 DAW Out**  | **ON**    | Off       | **ON**        |\n+---------------------------------------+-----------+-----------+---------------+</pre>"},{"type":"prose","html":"<em>Sync Flag Mandate</em>: Setting <strong>Sync: ON</strong> on <code>Output: Launchkey MK4 61 MIDI</code> transmits Ableton Live’s master MIDI clock into the Launchkey, slaving the hardware Arpeggiator and Step Sequencer to project tempo."}]}],"minutes":8},{"id":"launchkey-l-13-1-4","title":"13.1.4: MPE Port Deactivation Protocol","blocks":[{"type":"step","title":"13.1.4: MPE Port Deactivation Protocol","blocks":[{"type":"list","items":["<strong>MPE Setting</strong>: In the <code>MIDI Ports</code> disclosure list for the Input ports, ensure the <strong>MPE</strong> checkbox remains <strong>UNCHECKED / OFF</strong>.","<strong>Reasoning</strong>: Enabling MPE causes Live to listen to all channels across the port, breaking multi-timbral track isolation (Part A on Ch 1, Part B on Ch 2, Chords on Ch 3, Drums on Ch 10)."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-13-1-5","title":"13.1.5: Optical Handshake Validation & The 2×8 Focus Ring","blocks":[{"type":"step","title":"13.1.5: Optical Handshake Validation & The 2×8 Focus Ring","blocks":[{"type":"prose","html":"When the script connects successfully:"},{"type":"list","items":["<strong>Pad Telemetry</strong>: Hold <code>Shift</code> on the hardware. Pads 1, 2, 3, 4 (Plugin, Mixer, Sends, Transport) and Pad 9 (DAW) illuminate in <strong>bright/dim Pink and Blue</strong>.","<strong>Session View Focus Ring</strong>: A colored <strong>2 × 8 rectangular highlight ring</strong> immediately appears in Ableton Live’s Session View, demarcating the 16 clip slots addressed by the Launchkey pads."],"ordered":true},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">       ABLETON LIVE 12 SESSION VIEW (2x8 FOCUS RING)\n      Track 1     Track 2     Track 3     Track 4 ... Track 8\n    ┌─────────────────────────────────────────────────────────┐\nSc 1│ [ Clip 1 ]  [ Clip 2 ]  [ Clip 3 ]  [ Clip 4 ] ...      │ ◄── Top Row (Pads 1–8)\nSc 2│ [ Clip 9 ]  [ Clip 10]  [ Clip 11]  [ Clip 12] ...      │ ◄── Bottom Row (Pads 9–16)\n    └─────────────────────────────────────────────────────────┘</pre>"}]}],"minutes":8},{"id":"launchkey-l-13-1-6","title":"13.1.6: Legacy Compatibility Constraints","blocks":[{"type":"step","title":"13.1.6: Legacy Compatibility Constraints","blocks":[{"type":"list","items":["<strong>Live 11.3.26+</strong>: Supported; identical Python script architecture, though menu labels refer to \"Preferences\" instead of \"Settings\".","<strong>Live 10 and Earlier</strong>: <strong>UNSUPPORTED</strong>. Older versions lack the <code>Launchkey MK4</code> native Python control surface script. The controller operates only as a generic MIDI keyboard without Session clip launching, native plugin paging, or retrospective Capture MIDI integration."],"ordered":true}]},{"type":"step","title":"Operational Rules Summary","blocks":[{"type":"list","items":["<strong>mustCover</strong>: Exact script name (<code>Launchkey MK4</code>); DAW port binding; full 4-row Track/Sync/Remote matrix; MPE disabled rule; optical Shift pad success check; 2×8 Session focus ring; Live 11 vs Live 10 limits.","<strong>mustNotCover</strong>: Selecting Launchkey MK3 or generic scripts; claiming Live 10 supports the native MK4 script."],"ordered":false}]},{"type":"step","title":"Practical Guided Task & Assessment Checkpoint","blocks":[{"type":"prose","html":"<strong>Task</strong>: Open Ableton Live 12 Standard. Configure the Control Surface row and the 4-row MIDI Port matrix according to the authoritative table. Verify the 2×8 Session focus ring appears in Session View."},{"type":"prose","html":"<strong>Checkpoint Validation</strong>:"},{"type":"list","items":["Control Surface is <code>Launchkey MK4</code> bound to DAW ports.","Four-row Track/Sync/Remote table matches the official matrix.","Holding <code>Shift</code> illuminates DAW-native pads in pink and blue.","2×8 Session focus ring is visible on the Live screen."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"launchkey-m-13-2-2","code":"13.2","title":"Ableton Live 12 Standard Native Control Surface","blurb":"Once the native control surface script is initialized, the Launchkey MK4 61 provides deep, bidirectional control over Ableton Live 12. This module details Session View focus ring navigation, track soft-arming, 8-channel banking, vertical sc","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-39","title":"Section overview","blocks":[{"type":"step","title":"Section 13.2 — Live Session Navigation & Device Interaction","blocks":[{"type":"heading","text":"Module Overview","level":3},{"type":"prose","html":"Once the native control surface script is initialized, the Launchkey MK4 61 provides deep, bidirectional control over Ableton Live 12. This module details Session View focus ring navigation, track soft-arming, 8-channel banking, vertical scene navigation, native device parameter paging, device chain stepping, and the specialized Live-specific Transport rotary encoder map."},{"type":"heading","text":"Learning Objectives","level":3},{"type":"list","items":["Navigate the 2×8 Session View focus ring across tracks and scenes.","Formulate the soft-arming behavior of single-track navigation (<code>Track &lt; &gt;</code>).","Execute 8-track mixer banking using <code>Shift + Track &lt; &gt;</code>.","Command virtual instruments and effects in <strong>Plugin Mode</strong>, including parameter banking and device switching (<code>Shift + Encoder Bank</code>).","Detail the Live-specific 8-encoder <strong>Transport Mode</strong> map, including view-dependent zoom dynamics.","Interpret the OLED <code>No Markers</code> telemetry state."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-13-2-1","title":"13.2.1: Session View 2×8 Focus Ring Navigation","blocks":[{"type":"step","title":"13.2.1: Session View 2×8 Focus Ring Navigation","blocks":[{"type":"prose","html":"The 2×8 colored highlight box in Session View outlines the 16 clip slots currently mapped to the Launchkey pads:"},{"type":"list","items":["<strong>Horizontal Track Movement (<code>Track &lt; &gt;</code>)</strong>:","Moves the single-track focus left or right.","Automatically <strong>soft-arms</strong> the selected track (routing keybed performance to that instrument).","<em>Ring Follow Rule</em>: The 2×8 focus ring remains stationary until track navigation moves past the 8th track of the current bank, at which point the ring shifts to encompass the newly selected track.","<strong>Horizontal 8-Track Banking (<code>Shift + Track &lt; &gt;</code>)</strong>:","Instantly shifts the 2×8 focus ring by a full 8 tracks (e.g., Tracks 1–8 -&gt; Tracks 9–16).","<strong>Vertical Scene Navigation (<code>Pad Bank Up / Down</code>)</strong>:","Shifts the 2×8 focus ring up or down by 2 scene rows at a time, moving the pads across project scenes."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-13-2-2","title":"13.2.2: Live Plugin Encoder Mode & Device Navigation","blocks":[{"type":"step","title":"13.2.2: Live Plugin Encoder Mode & Device Navigation","blocks":[{"type":"prose","html":"When Encoder Mode is set to <strong>Plugin</strong> (<code>Shift + Pad 1</code>):"},{"type":"list","items":["<strong>Parameter Paging</strong>: Encoders 1–8 automatically map to the first 8 macro/parameters of the focused Live device.","Pressing <code>Encoder Bank Up / Down</code> cycles through additional parameter pages (e.g., Banks 2, 3, 4).","<strong>Device Chain Stepping (<code>Shift + Encoder Bank Up / Down</code>)</strong>:","Holding <code>Shift</code> and pressing <code>Encoder Bank Up / Down</code> steps sequentially through adjacent plugins/devices on the selected track's device chain (e.g., moving from a Drift synth to an EQ Eight to a Delay).","The OLED screen displays both the <strong>Device Name</strong> and the active <strong>Parameter Page</strong> (e.g., <code>Drift: Filter/Env</code>)."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-13-2-3","title":"13.2.3: Live Mixer & Sends Modes","blocks":[{"type":"step","title":"13.2.3: Live Mixer & Sends Modes","blocks":[{"type":"list","items":["<strong>Mixer Mode (<code>Shift + Pad 2</code>)</strong>: Encoders 1–8 control Track Pan for the 8 tracks within the focus ring.","<strong>Sends Mode (<code>Shift + Pad 3</code>)</strong>: Encoders 1–8 control Send A levels. Pressing <code>Encoder Bank Up / Down</code> switches control to Send B, Send C, etc."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-13-2-4","title":"13.2.4: Authoritative Live-Specific Transport Encoder Map","blocks":[{"type":"step","title":"13.2.4: Authoritative Live-Specific Transport Encoder Map","blocks":[{"type":"prose","html":"When Encoder Mode is set to <strong>Transport</strong> (<code>Shift + Pad 4</code>), the Launchkey MK4 loads a dedicated Ableton Live control map that differs from the universal generic DAW transport map:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|              AUTHORITATIVE LIVE 12 TRANSPORT ENCODER MAP                      |\n+---------------+-----------------------+---------------------------------------+\n| Encoder #     | Live Control Target   | Operational Function                  |\n+---------------+-----------------------+---------------------------------------+\n| **Encoder 1** | **Playback Position** | Scrubs the arrangement/song playhead  |\n| **Encoder 2** | **Zoom Horizontal**   | View-Dependent Horizontal Zoom/Scroll |\n| **Encoder 3** | **Zoom Vertical**     | View-Dependent Vertical Zoom/Scroll   |\n| **Encoder 4** | **Loop Start**        | Adjusts timeline Loop Start marker    |\n| **Encoder 5** | **Loop End**          | Adjusts timeline Loop End marker      |\n| **Encoder 6** | **Marker Select**     | Jumps sequentially between Cue Markers|\n| **Encoder 7** | *(Unassigned / Empty)*| Sends no data / reserved              |\n| **Encoder 8** | **Tempo**             | Adjusts Ableton Live Master BPM       |\n+---------------+-----------------------+---------------------------------------+</pre>"}]}],"minutes":8},{"id":"launchkey-l-13-2-5","title":"13.2.5: View-Dependent Zoom Dynamics","blocks":[{"type":"step","title":"13.2.5: View-Dependent Zoom Dynamics","blocks":[{"type":"prose","html":"Encoders 2 and 3 dynamically adapt their behavior based on which Live window is active:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                      VIEW-DEPENDENT ZOOM/SCROLL BEHAVIOR                      |\n+-------------------+---------------------------+-------------------------------+\n| Active Live View  | Encoder 2 (Zoom H)        | Encoder 3 (Zoom V)            |\n+-------------------+---------------------------+-------------------------------+\n| **Arrangement**   | Zooms in/out on playhead  | Expands/contracts track height|\n+-------------------+---------------------------+-------------------------------+\n| **Session View**  | Scrolls tracks left/right | Scrolls scenes up/down        |\n+-------------------+---------------------------+-------------------------------+</pre>"}]}],"minutes":8},{"id":"launchkey-l-13-2-6","title":"13.2.6: Cue Marker Telemetry & Empty States","blocks":[{"type":"step","title":"13.2.6: Cue Marker Telemetry & Empty States","blocks":[{"type":"list","items":["Turning Encoder 6 steps the playhead between user-defined Cue Markers / Song Locators in Arrangement View.","If the current Live set contains zero Cue Markers, the Launchkey OLED screen displays: <code>No Markers</code>."],"ordered":false}]},{"type":"step","title":"Operational Rules Summary","blocks":[{"type":"list","items":["<strong>mustCover</strong>: 2×8 Session focus ring; track soft-arming; 8-track banking (<code>Shift + Track &lt; &gt;</code>); scene vertical navigation (<code>Pad Bank Up/Down</code>); Plugin mode parameter banking + device switching (<code>Shift + Encoder Bank</code>); full 8-encoder Live Transport table (including empty slot 7 and tempo on 8); view-dependent zoom; <code>No Markers</code> display state.","<strong>mustNotCover</strong>: Using the universal common-DAW transport map as if it applied to Live (Live uses this dedicated map)."],"ordered":false}]},{"type":"step","title":"Practical Guided Task & Assessment Checkpoint","blocks":[{"type":"prose","html":"<strong>Task</strong>: In an Ableton Live set containing multiple devices on a track and at least two cue markers: engage Plugin Mode, step between devices using <code>Shift + Encoder Bank Up / Down</code>, engage Transport Mode (<code>Shift + Pad 4</code>), scrub playback position with Encoder 1, and test view-dependent zoom in Arrangement versus Session View."},{"type":"prose","html":"<strong>Checkpoint Validation</strong>:"},{"type":"list","items":["OLED screen displays exact device names and parameter banks.","Transport encoders accurately control Playback Position, View Zoom, Cue Markers, and BPM."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"launchkey-m-13-3-3","code":"13.3","title":"Ableton Live 12 Standard Native Control Surface","blurb":"This module details the deep execution mechanics of hardware transport recording across Ableton Live 12's dual operational paradigms (Session View vs. Arrangement View), retrospective MIDI capture, and the bidirectional SysEx handshake that","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-40","title":"Section overview","blocks":[{"type":"step","title":"Section 13.3 — Live Transport Execution & Global Scale Sync","blocks":[{"type":"heading","text":"Module Overview","level":3},{"type":"prose","html":"This module details the deep execution mechanics of hardware transport recording across Ableton Live 12's dual operational paradigms (Session View vs. Arrangement View), retrospective MIDI capture, and the bidirectional SysEx handshake that keeps the Launchkey's internal Scale and Chord engines locked to Live's Global Scale."},{"type":"heading","text":"Learning Objectives","level":3},{"type":"list","items":["Formulate the dynamic target routing of the hardware <code>Record</code> button based on active Live view focus.","Execute retrospective recording via <code>Capture MIDI</code> without pre-arming or manual timeline setup.","Formulate the bidirectional SysEx protocol that synchronizes Ableton Live 12 Global Scale with the Launchkey hardware."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-13-3-1","title":"13.3.1: Dynamic Recording Targeting (Session vs. Arrangement)","blocks":[{"type":"step","title":"13.3.1: Dynamic Recording Targeting (Session vs. Arrangement)","blocks":[{"type":"prose","html":"The physical <code>Record</code> button on the Launchkey MK4 61 dynamically alters its execution target based on which window is in focus within Ableton Live 12:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                    DYNAMIC RECORDING TARGETING IN LIVE 12                     |\n+-------------------+-----------------------+-----------------------------------+\n| Active Live Window| Physical Record Action| Ableton Live Engine Target        |\n+-------------------+-----------------------+-----------------------------------+\n| **Session View**  | Press [ Record ]      | Engages **Session Record**:       |\n|                   |                       | Records into highlighted clip     |\n|                   |                       | slots on armed tracks / overdub   |\n+-------------------+-----------------------+-----------------------------------+\n| **Arrangement**   | Press [ Record ]      | Engages **Arrangement Record**:   |\n|                   |                       | Punches in recording along the    |\n|                   |                       | linear arrangement timeline       |\n+-------------------+-----------------------+-----------------------------------+</pre>"}]}],"minutes":8},{"id":"launchkey-l-13-3-2","title":"13.3.2: Retrospective MIDI Capture Integration","blocks":[{"type":"step","title":"13.3.2: Retrospective MIDI Capture Integration","blocks":[{"type":"prose","html":"Pressing the dedicated <code>Capture MIDI</code> button executes Live's retrospective listening buffer:"},{"type":"list","items":["<strong>Mechanism</strong>: Live continuously monitors incoming MIDI from armed tracks even when playback is stopped or running without recording engaged.","<strong>Execution</strong>: If a performer plays an expressive phrase during playback, pressing <code>Capture MIDI</code> analyzes the timing, creates a new MIDI clip matching the phrase length, sets the project tempo (if empty), and places the notes into the active clip slot."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-13-3-3","title":"13.3.3: Bidirectional Global Scale Synchronization","blocks":[{"type":"step","title":"13.3.3: Bidirectional Global Scale Synchronization","blocks":[{"type":"prose","html":"Ableton Live 12 introduced a centralized <strong>Global Scale</strong> architecture in the master transport bar."},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">       BIDIRECTIONAL GLOBAL SCALE SYSEX HANDSHAKE\n+───────────────────────────────────────────────────────────────+\n| 1. User sets Key/Scale in Ableton Live 12 (e.g., \"D Dorian\")   |\n|                                │                              |\n|                                ▼ (SysEx Handshake via DAW Out)|\n| 2. Launchkey MK4 Script automatically transmits Scale data     |\n|                                │                              |\n|                                ▼                              |\n| 3. Launchkey updates internal Scale Engine to \"D Dorian\"       |\n|    and reloads Chord Map Chord Set to D Dorian Harmonic Bank  |\n+───────────────────────────────────────────────────────────────+</pre>"},{"type":"list","items":["<strong>Set Initialization</strong>: Opening an existing Live set automatically synchronizes the Launchkey hardware to that project's stored scale without manual intervention."],"ordered":false}]},{"type":"step","title":"Operational Rules Summary","blocks":[{"type":"list","items":["<strong>mustCover</strong>: Session vs Arrangement record targets; Capture MIDI execution; bidirectional Global Scale SysEx synchronization.","<strong>mustNotCover</strong>: Speculation regarding Arrangement clip launching (Session View is the clip launching domain)."],"ordered":false}]},{"type":"step","title":"Practical Guided Task & Assessment Checkpoint","blocks":[{"type":"prose","html":"<strong>Task</strong>: In Ableton Live 12, change the Global Scale to <code>E Minor</code>. Observe the Launchkey OLED screen and confirm the hardware automatically updates its internal Scale to <code>E Minor</code>. Record one clip in Session View and one linear take in Arrangement View using the hardware Record button."},{"type":"prose","html":"<strong>Checkpoint Validation</strong>:"},{"type":"list","items":["Launchkey Scale and Chord Map automatically synchronize to Live's Global Scale.","Hardware Record button accurately targets Session clip slots in Session View and timeline recording in Arrangement View."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"launchkey-m-13-4-4","code":"13.4","title":"Ableton Live 12 Standard Native Control Surface","blurb":"While the dedicated Launchkey MK4 Python script handles the vast majority of DAW mixing and device control, specialized performance workflows often require manual, user-defined MIDI mappings. This module details the technical boundaries bet","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-41","title":"Section overview","blocks":[{"type":"step","title":"Section 13.4 — Manual MIDI Overrides & Live Mapping Architecture","blocks":[{"type":"heading","text":"Module Overview","level":3},{"type":"prose","html":"While the dedicated <code>Launchkey MK4</code> Python script handles the vast majority of DAW mixing and device control, specialized performance workflows often require manual, user-defined MIDI mappings. This module details the technical boundaries between the native script and manual MIDI Map Mode, Live's Takeover Modes, and the port isolation strategy required to prevent control surface corruption."},{"type":"heading","text":"Learning Objectives","level":3},{"type":"list","items":["Formulate the technical separation between script-governed DAW modes (Interface 2) and user-programmable Custom Modes (Interface 1).","Execute manual parameter mappings via Ableton Live’s MIDI Map Mode (<code>Ctrl + M</code> / <code>Cmd + M</code>).","Contrast Ableton Live’s three Takeover Modes: <strong>None</strong>, <strong>Pickup</strong>, and <strong>Value Scaling</strong>.","Apply the port isolation rule to prevent fighting the native control surface script.","Complete Assessment Gate J."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-13-4-1","title":"13.4.1: Custom Modes vs. The Native Control Surface Script","blocks":[{"type":"step","title":"13.4.1: Custom Modes vs. The Native Control Surface Script","blocks":[{"type":"prose","html":"A foundational principle of Launchkey MK4 architecture is port isolation:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                    PORT ISOLATION ARCHITECTURE IN LIVE 12                     |\n+-------------------+---------------------------+-------------------------------+\n| Control Plane     | Physical Interface Used   | Operational Domain            |\n+-------------------+---------------------------+-------------------------------+\n| **Native Script** | **Interface 2 (DAW Port)**| Session Clips, Plugin Paging, |\n|                   |                           | Mixer Volume/Pan, Transport   |\n+-------------------+---------------------------+-------------------------------+\n| **Custom Modes**  | **Interface 1 (MIDI Port)**| Manual MIDI Map Mode, Custom  |\n|                   |                           | VST Racks, Third-Party Maps   |\n+-------------------+---------------------------+-------------------------------+</pre>"},{"type":"prose","html":"<em>CRITICAL RULE OF PORT ISOLATION</em>: When manually mapping controls in Ableton Live, <strong>always switch the Launchkey to a Custom Mode (Custom 1–4)</strong>. Custom Modes transmit on Interface 1 (<code>Remote: ON</code>), allowing custom mappings without overriding or corrupting the native Session script running on Interface 2."}]}],"minutes":8},{"id":"launchkey-l-13-4-2","title":"13.4.2: Ableton Live Takeover Modes (Manual Mapping)","blocks":[{"type":"step","title":"13.4.2: Ableton Live Takeover Modes (Manual Mapping)","blocks":[{"type":"prose","html":"In Ableton Live's MIDI Settings (<code>Link, Tempo &amp; MIDI</code> -&gt; <code>Takeover Mode</code>), three algorithms govern how continuous hardware controls take control of software parameters:"},{"type":"list","items":["<strong>None</strong>:","The software value immediately <strong>jumps</strong> to match the physical position of the hardware encoder or fader as soon as it is moved.","<strong>Pickup</strong>:","The software value remains unchanged until the physical fader or encoder travels across and <strong>intersects the exact stored software value</strong>. Once crossed, the physical control takes active tracking.","<strong>Value Scaling</strong>:","Proportional mathematical scaling. Moving the physical control gradually accelerates or decelerates the software parameter toward the physical position, achieving smooth convergence without abrupt jumps."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-13-4-3","title":"13.4.3: Managing the Live Mapping Browser","blocks":[{"type":"step","title":"13.4.3: Managing the Live Mapping Browser","blocks":[{"type":"list","items":["Press <code>Ctrl + M</code> (Windows) or <code>Cmd + M</code> (macOS) to engage Live's <strong>MIDI Map Mode</strong> (mappable parameters turn blue).","The <strong>Mapping Browser</strong> in Live's left sidebar displays all active manual mappings, including Note/CC assignments, channel indices, and Min/Max value clamps.","To delete a manual mapping, select it in the Mapping Browser and press <code>Delete</code>."],"ordered":true}]},{"type":"step","title":"Operational Rules Summary","blocks":[{"type":"list","items":["<strong>mustCover</strong>: Script vs Custom Mode separation; manual MIDI Map mode; Takeover modes (None, Pickup, Value Scaling); mapping strictly on Interface 1 (MIDI port); leaving DAW port to the surface.","<strong>mustNotCover</strong>: Deleting the Launchkey MK4 script as a troubleshooting step."],"ordered":false}]},{"type":"step","title":"Assessment Gate J (Ableton Live 12 Native Surface Validation)","blocks":[{"type":"prose","html":"<strong>Objective</strong>: Demonstrate complete operational mastery of the native Ableton Live 12 control surface script, routing matrix, and navigation."},{"type":"prose","html":"<strong>Self-Assessment Checklist</strong>:"},{"type":"list","items":["[ ] Live 12 Settings display <code>Control Surface: Launchkey MK4</code> bound to <code>DAW In</code> and <code>DAW Out</code>.","[ ] All 4 rows of the official Track/Sync/Remote matrix are verified and active (with Sync ON for Output MIDI).","[ ] Holding <code>Shift</code> illuminates DAW, Plugin, Mixer, Sends, and Transport pads in pink/blue.","[ ] The 2×8 Session focus ring is clearly visible in Session View and navigates via <code>Track &lt; &gt;</code> and <code>Pad Bank Up / Down</code>.","[ ] Capture MIDI, Quantise, Undo, and Metronome buttons execute correctly from the hardware."],"ordered":true}]}],"minutes":8}],"exercises":[]}]};
